"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["35369"],{73107(e,n,t){t.r(n),t.d(n,{metadata:()=>s,default:()=>c,frontMatter:()=>i,contentTitle:()=>o,toc:()=>h,assets:()=>l});var s=JSON.parse('{"id":"qiangguo/maopoemflaws1","title":"","description":"Girl Who Likes Mathematics","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/qiangguo/maopoemflaws1.md","sourceDirName":"qiangguo","slug":"/qiangguo/maopoemflaws1","permalink":"/en/qiangguo/maopoemflaws1","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"maopoemflaws1","title":"","hide_table_of_contents":true,"sidebar_label":"An objective evaluation of flaws in Mao Zedong\'s poetry (Part 1)"},"sidebar":"qiangguoSidebar","previous":{"title":"An objective evaluation of Mao Zedong\'s poetry","permalink":"/en/qiangguo/commentsonmaopoems"},"next":{"title":"An objective evaluation of flaws in Mao Zedong\'s poetry (Part 2)","permalink":"/en/qiangguo/maopoemflaws2"}}'),a=t(74848),r=t(28453);let i={id:"maopoemflaws1",title:"",hide_table_of_contents:!0,sidebar_label:"An objective evaluation of flaws in Mao Zedong's poetry (Part 1)"},o="An Objective Evaluation of the Flaws in Mao Zedong's Poetry (Part One)",l={},h=[];function d(e){let n={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,r.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(n.header,{children:(0,a.jsx)(n.h1,{id:"an-objective-evaluation-of-the-flaws-in-mao-zedongs-poetry-part-one",children:"An Objective Evaluation of the Flaws in Mao Zedong's Poetry (Part One)"})}),"\n",(0,a.jsxs)(n.blockquote,{children:["\n",(0,a.jsx)(n.p,{children:"Girl Who Likes Mathematics"}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"Probably due to time constraints, Mao Zedong never deeply studied the true art of poetry. In a certain sense, Mao Zedong was the type who completed his creative works through sheer force of vital energy. But due to limitations in poetic talent, this vital-energy-driven approach could not reach the heights of Li Bai, Su Shi, and other masters, and this is also a reason why Mao Zedong's shi poems are not as good as his ci lyrics. Because shi poems demand greater originality and stricter tonal patterns, ci lyrics are comparatively easier. Here, let us first provide an objective evaluation of the seven-character regulated verse, the main type among Mao Zedong's shi poems."}),"\n",(0,a.jsx)(n.p,{children:'First, for seven-character regulated verse, the prosodic requirements are very high. The rhymes generally cannot use ci rhyme tables but must follow Pingshui rhymes exclusively. Mao Zedong did not do very well on this point -- many of his seven-character regulated verses rhyme according to ci conventions. For example, in both "In Reply to Mr. Liu Yazi" and "The People\'s Liberation Army Captures Nanjing," the character "jiang" from the Sanjiang rhyme group is mixed with the Qiyang rhyme group -- acceptable in ci but absolutely impermissible in seven-character regulated verse. The same error occurs in "The Long March," where the Shisi Han and Shiwu Shan rhyme groups are mixed; and in "Winter Clouds" and "Mourning Comrade Luo Ronghuan," where the Sizhi and Wuwei rhyme groups are mixed. Probably influenced by Mao Zedong, many later writers of classical poetry also began using ci or modern rhymes, but this has nothing to do with authentic seven-character regulated verse. A thousand-plus years of history have proven that Pingshui rhymes do not constrain the thinking of true poets, and the practice of relaxing rhyme requirements has not produced anything remarkable.'}),"\n",(0,a.jsx)(n.p,{children:'Second, the parallelism requirements in seven-character regulated verse are very strict, but Mao Zedong did not execute these very well. For example: "The Five Ridges wind and twist like gentle ripples, / The Wumeng range rolls by like balls of mud. / Gold Sand River\'s waters beat the warm cloud cliffs, / Dadu Bridge\'s iron chains stretch out in cold." Both middle couplets can only be said to barely match up. Moreover, the character "qian" (thousand) and "shan" (mountain) appear in both the opening and closing couplets, while "shui" (water) appears in both the opening and neck couplets -- this is completely unacceptable in seven-character regulated verse. If we apply even higher standards, where parallel couplets cannot exhibit "clasped palms" (redundant mirroring), there are even more flawed areas. For example: "Red rain, following the heart, turns into waves; / Green mountains, with purpose, transform into bridges. / The sky links the Five Ridges where silver hoes fall; / The earth shakes the Three Rivers where iron arms swing." Both couplets exhibit clasped palms, with the latter pair being especially egregious.'}),"\n",(0,a.jsx)(n.p,{children:'As for the relationships of introduction, development, turn, and conclusion between couplets, and the alternation of sentence structures -- those requirements are even higher. Mao Zedong did not perform well in these areas. The "turn" in the neck couplet in particular is almost never achieved. As a result, entire poems become little more than lists of couplets. Because Mao Zedong liked to use words with grand imagery, under such imagery ordinary readers tend not to notice these issues. But a truly good seven-character regulated verse is an organic whole, a living thing, with a life-like flow between couplets. Without meeting this requirement, a seven-character regulated verse cannot, at least artistically, be considered good.'}),"\n",(0,a.jsx)(n.p,{children:"In fact, Mao Zedong himself was very aware of the problems with his seven-character regulated verse, and explicitly stated in his letter to Chen Yi that he was not satisfied with any of his seven-character regulated verses, and that his ci lyrics were somewhat better. This is quite objective -- Mao Zedong's ci lyrics are indeed better than his shi poems. A good poem is not achieved by simply piling up grand imagery. The complexity involved is far from simple. Consider that in Chinese history, those who wrote seven-character regulated verse are as numerous as the hairs on a cow, yet truly good seven-character regulated verses probably number less than one percent. Even Du Fu, Li Shangyin, and Huang Tingjian did not produce a good one every time. Below are some seven-character regulated verses for comparison from an artistic standpoint."}),"\n",(0,a.jsxs)(n.p,{children:["Du Fu",(0,a.jsx)("br",{}),"\nClimbing High",(0,a.jsx)("br",{})]}),"\n",(0,a.jsxs)(n.p,{children:["The wind is sharp, the sky high, apes cry out in grief; by clear islets and white sand, birds wheel and return.",(0,a.jsx)("br",{}),"\nBoundless falling leaves drift down in rustling waves; the endless Yangtze rolls on and on.",(0,a.jsx)("br",{}),"\nTen thousand miles from home in sorrowful autumn, forever a traveler; a hundred years of illness, alone I climb this terrace.",(0,a.jsx)("br",{}),"\nIn hardship I bitterly hate these frost-thick temples; in dejection I have newly put down the muddy wine cup."]}),"\n",(0,a.jsx)(n.p,{children:"Night in the Tower"}),"\n",(0,a.jsxs)(n.p,{children:["At year\u2019s end, yin and yang press the daylight short; at heaven\u2019s edge, frost and snow clear from the cold night sky.",(0,a.jsx)("br",{}),"\nAt fifth watch, drums and horns sound tragic and grand; over the Three Gorges, stars and Milky Way tremble in reflection.",(0,a.jsx)("br",{}),"\nIn the wild, the crying of a thousand households tells of war; in scattered places, frontier songs rise from fishers and woodcutters.",(0,a.jsx)("br",{}),"\nCrouching Dragon and Galloping Horse end in yellow earth; in human affairs, letters and news are endlessly desolate."]}),"\n",(0,a.jsx)(n.p,{children:"Autumn Meditations"}),"\n",(0,a.jsxs)(n.p,{children:["Kunming Pool\u2019s waters still bear the Han dynasty\u2019s achievements; Emperor Wu\u2019s battle banners stand before my eyes.",(0,a.jsx)("br",{}),"\nThe Weaver Girl\u2019s loom-threads are empty in the night moon; the stone whale\u2019s scales stir in the autumn wind.",(0,a.jsx)("br",{}),"\nFloating wild-rice drifts with waves as dark clouds sink; cold dew chills lotus pods and drops their crimson powder.",(0,a.jsx)("br",{}),"\nAt the frontier passes, only bird paths reach the sky; across rivers and lakes, there is but one old fisherman."]}),"\n",(0,a.jsx)(n.p,{children:"Li Shangyin"}),"\n",(0,a.jsxs)(n.p,{children:["The brocade zither, for no reason, has fifty strings; each string and peg stirs thoughts of splendid years.",(0,a.jsx)("br",{}),"\nZhuang Zhou\u2019s dawn dream is lost among butterflies; King Wang\u2019s spring heart entrusts itself to cuckoos.",(0,a.jsx)("br",{}),"\nOn the bright moonlit sea, pearls hold tears; in sun-warmed Lantian, jade gives rise to mist.",(0,a.jsx)("br",{}),"\nThis feeling could become a memory to recall, yet even then, at that moment, it was already bewilderment."]}),"\n",(0,a.jsxs)(n.p,{children:["Far off, the high city\u2019s hundred-foot tower; beyond willow branches, all islets stretch away.",(0,a.jsx)("br",{}),"\nJia Yi in youth shed tears in vain; Wang Can, in spring, traveled farther still.",(0,a.jsx)("br",{}),"\nI always long to return to rivers and lakes in white-haired age; I wish to turn heaven and earth and enter a little boat.",(0,a.jsx)("br",{}),"\nWho knew rotten rats could become a delicacy? Suspecting young phoenixes has never ceased."]}),"\n",(0,a.jsxs)(n.p,{children:["Sudden Rain at Youmei Hall",(0,a.jsx)("br",{}),"\nSu Shi"]}),"\n",(0,a.jsxs)(n.p,{children:["Beneath the travelers\u2019 feet, one peal of thunder; thick stubborn clouds fill the hall, impossible to part.",(0,a.jsx)("br",{}),"\nBeyond the sky, black wind blows and the sea stands upright; from eastern Zhejiang, flying rain crosses the river.",(0,a.jsx)("br",{}),"\nRipples blaze so brightly they bulge the golden cup; a thousand pounding strokes clang like Jie drums urging on.",(0,a.jsx)("br",{}),"\nIt rouses the banished immortal, springing wine to the surface; overturned from the merfolk chamber pours out white jade brilliance."]}),"\n",(0,a.jsxs)(n.p,{children:["Post-Autumn Meditations No. 13 (one selected from eight)",(0,a.jsx)("br",{}),"\nQian Qianyi"]}),"\n",(0,a.jsxs)(n.p,{children:["At earth\u2019s edge, Yashan slants in a single line; from now on, it no longer belongs to China.",(0,a.jsx)("br",{}),"\nNo longer a fish-belly place to sacrifice one\u2019s life; much less dragon-saliva drifting on sea rafts?",(0,a.jsx)("br",{}),"\nGazing to exhaustion at passes and rivers, no Han banners remain; blown to shreds are sun and moon, now Hu reed-pipes.",(0,a.jsx)("br",{}),"\nChang\u2019e has grown old with nowhere to return; only I, with silver wheel, weep for cassia blossoms."]}),"\n",(0,a.jsxs)(n.p,{children:["Autumn Heart",(0,a.jsx)("br",{}),"\nGong Zizhen"]}),"\n",(0,a.jsxs)(n.p,{children:["My autumn heart is like the sea, and like the tide again; only this autumn soul cannot be summoned.",(0,a.jsx)("br",{}),"\nDimly, tulip fragrance clings to my arm; upright, an ancient jade pendant rests at my waist.",(0,a.jsx)("br",{}),"\nIn the cold northwest, whose sword is it? In the southeast, flute-notes fill several places.",(0,a.jsx)("br",{}),"\nStars as large as dippers blaze beyond count; in the long sky, one moon drops to the forest tips."]})]})}function c(e={}){let{wrapper:n}={...(0,r.R)(),...e.components};return n?(0,a.jsx)(n,{...e,children:(0,a.jsx)(d,{...e})}):d(e)}},28453(e,n,t){t.d(n,{R:()=>i,x:()=>o});var s=t(96540);let a={},r=s.createContext(a);function i(e){let n=s.useContext(r);return s.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function o(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:i(e.components),s.createElement(r.Provider,{value:n},e.children)}}}]);